package config

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// setupTmpHome redirects os.UserHomeDir() to a fresh temp dir and restores on cleanup.
// Sets both HOME (Unix/macOS) and USERPROFILE (Windows) so the redirect works cross-platform.
func setupTmpHome(t *testing.T) string {
	t.Helper()
	tmpDir := t.TempDir()
	t.Setenv("HOME", tmpDir)
	t.Setenv("USERPROFILE", tmpDir)
	return tmpDir
}

// ── ValidateContextName ──────────────────────────────────────────────────────

func TestValidateContextName_Valid(t *testing.T) {
	cases := []string{"default", "dev", "prod", "client-a", "ctx123", "a-b-c"}
	for _, name := range cases {
		t.Run(name, func(t *testing.T) {
			if err := ValidateContextName(name); err != nil {
				t.Errorf("unexpected error: %v", err)
			}
		})
	}
}

func TestValidateContextName_Invalid(t *testing.T) {
	cases := []string{"Dev", "PROD", "ctx_1", "ctx.x", "Ctx", "", "a b", "abc!"}
	for _, name := range cases {
		t.Run(name, func(t *testing.T) {
			if err := ValidateContextName(name); err == nil {
				t.Error("expected error, got nil")
			}
		})
	return contexts, nil
}

// LoadContext loads the configuration for a specific context
// contextName = "default" -> config.yaml
// contextName = "dev" -> config-dev.yaml
func LoadContext(contextName string) (*Config, error) {
	if err := ValidateContextName(contextName); err != nil {
		return nil, err
	}

	configPath, err := GetContextPath(contextName)
	if err != nil {
		return nil, err
	}

	// Check whether the file exists
	if _, err := os.Stat(configPath); os.IsNotExist(err) {
		return nil, fmt.Errorf("context '%s' does not exist (no file at %s): %w", contextName, configPath, ErrContextNotFound)
	}

	// Read and parse YAML
	data, err := os.ReadFile(configPath)
	if err != nil {
		return nil, err
	}

